EU.SEGS=SEGS;
var TEXTS="432633a1";     // version of the texts: blocks 09–10 must carry the same (data-dkc3-texts)
EU.TEXTS=TEXTS;
var LOC=null,cache=Object.create(null),has=Object.prototype.hasOwnProperty;
/* blocks 09–10 of another build number their phrases differently: data-i would point to other texts.
   Then the configurator stays in English (correct, only not translated) and says so in the console. */
function textsOk(){
  var bl=D.querySelectorAll('.dkc3-i18n'),seen=[],n=0,i;
  for(i=0;i<bl.length;i++){seen.push(bl[i].getAttribute('data-dkc3-texts')||'none');n+=bl[i].querySelectorAll('i[data-i]').length;}
  var ok=bl.length>0;for(i=0;i<seen.length;i++)if(seen[i]!==TEXTS)ok=false;
  EU.texts={need:TEXTS,blocks:seen,phrases:n,ok:ok};
  try{
    if(!bl.length)console.warn('DKC3: no translation blocks (09–10) on this page — the configurator is shown in English.');
    else if(!ok)console.warn('DKC3: translation blocks 09–10 have texts version '+seen.join(', ')+', this program (v'+(W.DKC3&&W.DKC3.ver||'?')+') needs '+TEXTS+' — the configurator is shown in English. Paste blocks 09–10 of the same build as block 01.');
    else if(n!==SEGS.length)console.warn('DKC3: translation blocks 09–10 hold '+n+' of '+SEGS.length+' phrases — one of them is missing, the rest stays in English.');
  }catch(e){}
  return ok;
}
function locMap(){
  if(LOC)return LOC;LOC=Object.create(null);
  if(lang==='en')return LOC;
  if(!textsOk())return LOC;
  var it=D.querySelectorAll('.dkc3-i18n i[data-i]');
  for(var i=0;i<it.length;i++){var k=SEGS[+it[i].getAttribute('data-i')];var v=it[i].textContent;if(k&&v&&v.replace(/\s+/g,' ').trim()!==k)LOC[k]=v.replace(/\s+/g,' ').trim();}
  return LOC;
}
function seg(t){ /* translate one plain-text piece of English, keeping its edge spaces */
  var k=t.replace(/\s+/g,' ').trim();if(!k)return t;
  var L=locMap();if(!L[k])return t;
  return t.match(/^\s*/)[0]+L[k]+t.match(/\s*$/)[0];
}
/* user-visible pieces of an HTML string or fragment: text between tags and a few attribute values.
   Shared by the build (to collect the words for the site translation) and the page (to translate). */
function dkPieces(s,cb){
  var out='',i=0,n=s.length,lt=s.indexOf('<'),gt=s.indexOf('>');
  var inTag=gt>=0&&(lt<0||gt<lt);
  while(i<n){
    if(inTag){var j=s.indexOf('>',i);var tag=j<0?s.slice(i):s.slice(i,j+1);
      tag=tag.replace(/((?:title|aria-label|placeholder|alt|data-label)=")([^"]*)(")/g,function(m,a,v,c){return a+cb(v)+c;});
      out+=tag;if(j<0)break;i=j+1;inTag=false;}
    else{var j=s.indexOf('<',i);var t=j<0?s.slice(i):s.slice(i,j);out+=cb(t);if(j<0)break;i=j;inTag=true;}
  }
  return out;
}

EU.localize=function(en){
  if(lang==='en'||!en)return en;
  if(en.indexOf('<')<0&&en.indexOf('>')<0)return seg(en);
  return dkPieces(en,seg);
};
var cacheN=[];
W.__T=EU.T=function(x){
  if(typeof x==='number'){var c=cacheN[x];if(c!==undefined)return c;return cacheN[x]=EU.localize(ENA[x]);}
  if(typeof x!=='string')return x;
  if(has.call(cache,x))return cache[x];
  var en=has.call(EN,x)?EN[x]:x;
  return cache[x]=EU.localize(en);
};
