var REV=null,REVK=null;
function revBuild(){REV=Object.create(null);REVK=[];
  Object.keys(RUA).forEach(function(id){var out=W.__T(+id);if(out&&out.length>2&&!(out in REV)){REV[out]=RUA[id];REVK.push(out);}
    var en=ENA[+id];if(en&&en!==out&&en.length>2&&!(en in REV)){REV[en]=RUA[id];REVK.push(en);}});
  REVK.sort(function(a,b){return b.length-a.length;});}
var revCache=Object.create(null),revN=0;
W.__RU=EU.ru=function(s){
  if(typeof s!=='string'||!s)return s;
  if(!REV)revBuild();
  if(s in REV)return REV[s];
  if(s in revCache)return revCache[s];
  var o=s;for(var i=0;i<REVK.length;i++){var k=REVK[i];if(o.indexOf(k)>=0)o=o.split(k).join(REV[k]);}
  if(++revN>5000){revCache=Object.create(null);revN=0;}
  return revCache[s]=o;
};
/* static markup of the app: text nodes and a few attributes */
var ATTRS=['data-label','title','aria-label','placeholder','alt','data-tip','data-title'];
var CYR=/[А-Яа-яЁё]/;
EU.trDom=function(root){
  var tw=D.createTreeWalker(root,NodeFilter.SHOW_TEXT,null),n,list=[];
  while((n=tw.nextNode()))list.push(n);
  /* the markup is English already (translated at build time); here it goes into the site language */
  if(lang==='en')return;
  list.forEach(function(n){var p=n.parentNode&&n.parentNode.nodeName;if(p==='SCRIPT'||p==='STYLE')return;var v=n.nodeValue;if(!/[A-Za-z]{2}/.test(v))return;
    var w=seg(v);if(w!==v)n.nodeValue=w;});
  var els=root.querySelectorAll('*');
  for(var i=0;i<els.length;i++)ATTRS.forEach(function(a){var v=els[i].getAttribute(a);if(v&&/[A-Za-z]{2}/.test(v)){var w=seg(v);if(w!==v)els[i].setAttribute(a,w);}});
};

/* ---- numbers ---- */
EU.money=function(n){return n==null?'—':Math.round(n).toLocaleString(EU.loc)+' €';};
EU.plural=function(n,one,few,many){
  var a=Math.abs(n);
  if(lang==='hu')return one;                        /* Hungarian: singular after numbers */
  if(lang==='sl'){var h=a%100;return h===1?one:(h>=2&&h<=4)?few:many;}
  return a===1?one:many;
};

/* ---- EU article codes: the engine works with RU-style codes (same digits = same product) ---- */
EU.art=function(a){return String(a||'').replace(/^(DK|TR)(\d{4})/,'$1/EU-$2');};
/* the address a visitor shares or prints; the partner mode (build/partner.js) points it to the public configurator */
EU.pub=EU.pub||function(u){return u;};
var ART_RE=/\b(DK|TR)(\d{4}[A-Z]?(?:-[A-Z0-9+]+)*)\b/g;
EU.artText=function(s){return typeof s==='string'?s.replace(ART_RE,'$1/EU-$2'):s;};
